modules["UI/Elements/Slider"] = function(...)
-- Slider.
local import = ...

local Card = import("UI/Card")
local Elements = import("UI/Elements/Base")
local Services = import("Core/Services")
local UserInputService = Services.UserInputService
local Fonts = import("Core/Fonts")
local FONT = Fonts.FONT
local Util = import("Core/Util")
local Create, Tween, Corner, Safe, SetFlag, IsPress, IsMove = Util.Create, Util.Tween, Util.Corner, Util.Safe, Util.SetFlag, Util.IsPress, Util.IsMove
local Binding = import("Theme/Binding")
local Bind, NewText = Binding.Bind, Binding.NewText

function Elements:AddSlider(opts)
	opts = opts or {}
	local window = self.Window
	local min, max = opts.Min or 0, opts.Max or 100
	local increment = opts.Increment or 1
	local suffix = opts.Suffix or ""
	local decimals = #(string.match(tostring(increment), "%.(%d+)") or "")
	local fmt = "%." .. decimals .. "f"
	local value = min

	local card, _, cy = Card(self, opts, 0.42)

	local valueLabel = NewText(window, card, "", {
		Size = UDim2.fromOffset(56, 20),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -14, 0, cy),
		TextXAlignment = Enum.TextXAlignment.Right,
		Font = FONT,
		TextSize = 13,
	}, "SubText")
	local track = Create("Frame", {
		Size = UDim2.new(0.34, 0, 0, 4),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -78, 0, cy),
		BackgroundTransparency = 0.7,
		BorderSizePixel = 0,
		Parent = card,
	})
	Bind(window, track, "BackgroundColor3", "Text")
	Corner(track, "pill")
	local fill = Create("Frame", {
		Size = UDim2.fromScale(0, 1),
		BorderSizePixel = 0,
		Parent = track,
	})
	Bind(window, fill, "BackgroundColor3", "Accent")
	Corner(fill, "pill")
	local thumb = Create("Frame", {
		Size = UDim2.fromOffset(18, 18),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		BorderSizePixel = 0,
		Parent = track,
	})
	Bind(window, thumb, "BackgroundColor3", "Text")
	Corner(thumb, "pill")
	local inner = Create("Frame", {
		Size = UDim2.fromOffset(10, 10),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		BorderSizePixel = 0,
		Parent = thumb,
	})
	Bind(window, inner, "BackgroundColor3", "Accent")
	Corner(inner, "pill")
	local hit = Create("TextButton", {
		Size = UDim2.new(1, 18, 0, 28),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		BackgroundTransparency = 1,
		Text = "",
		Parent = track,
	})

	local obj = { Instance = card }

	local function apply(v, silent, force)
		v = math.clamp(v, min, max)
		v = math.floor((v - min) / increment + 0.5) * increment + min
		v = math.clamp(tonumber(string.format(fmt, v)), min, max)
		if v == value and not force then
			return
		end
		value = v
		local alpha = (max == min) and 0 or (v - min) / (max - min)
		Tween(fill, { Size = UDim2.fromScale(alpha, 1) }, 0.08)
		Tween(thumb, { Position = UDim2.fromScale(alpha, 0.5) }, 0.08)
		valueLabel.Text = string.format(fmt, v) .. suffix
		SetFlag(opts, v)
		if not silent then
			Safe(opts.Callback, v)
		end
	end

	function obj:Set(v, silent)
		apply(v, silent, true)
	end
	function obj:Get()
		return value
	end

	local dragging = false
	local function fromInput(input)
		local alpha = math.clamp((input.Position.X - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
		apply(min + (max - min) * alpha)
	end

	hit.InputBegan:Connect(function(input)
		if IsPress(input) then
			dragging = true
			Tween(thumb, { Size = UDim2.fromOffset(22, 22) }, 0.12, Enum.EasingStyle.Back)
			if self.Page then
				self.Page.ScrollingEnabled = false
			end
			fromInput(input)
		end
	end)
	window:_connect(UserInputService.InputChanged, function(input)
		if dragging and IsMove(input) then
			fromInput(input)
		end
	end)
	window:_connect(UserInputService.InputEnded, function(input)
		if dragging and IsPress(input) then
			dragging = false
			Tween(thumb, { Size = UDim2.fromOffset(18, 18) }, 0.15)
			if self.Page then
				self.Page.ScrollingEnabled = true
			end
		end
	end)

	apply(opts.Default or min, true, true)
	return obj
end

return Elements
end

modules["UI/Elements/Textbox"] = function(...)
-- Textbox.
local import = ...

local Card = import("UI/Card")
local Elements = import("UI/Elements/Base")
local Fonts = import("Core/Fonts")
local FONT = Fonts.FONT
local Util = import("Core/Util")
local Create, Tween, Corner, Pad, Safe, SetFlag = Util.Create, Util.Tween, Util.Corner, Util.Pad, Util.Safe, Util.SetFlag
local Binding = import("Theme/Binding")
local Bind, Themed, Stroke = Binding.Bind, Binding.Themed, Binding.Stroke

function Elements:AddTextbox(opts)
	opts = opts or {}
	local window = self.Window
	local card, _, cy = Card(self, opts, 0.45)

	local box = Create("TextBox", {
		Size = UDim2.new(0.38, 0, 0, 30),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -14, 0, cy),
		BorderSizePixel = 0,
		Text = opts.Default or "",
		PlaceholderText = opts.Placeholder or "",
		TextXAlignment = Enum.TextXAlignment.Left,
		Font = FONT,
		TextSize = 13,
		ClearTextOnFocus = opts.ClearOnFocus == true,
		ClipsDescendants = true,
		Parent = card,
	})
	Themed(window, box, {
		BackgroundColor3 = "Control",
		BackgroundTransparency = "ControlTransparency",
		TextColor3 = "Text",
		PlaceholderColor3 = "SubText",
	})
	Corner(box, 4)
	Stroke(window, box, "Stroke", "StrokeTransparency")
	Pad(box, 8, 0, 8, 0)
	local line = Create("Frame", {
		Size = UDim2.new(0, 0, 0, 2),
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.fromScale(0.5, 1),
		BorderSizePixel = 0,
		Parent = box,
	})
	Bind(window, line, "BackgroundColor3", "Accent")

	box.Focused:Connect(function()
		Tween(line, { Size = UDim2.new(1, 0, 0, 2) }, 0.2)
	end)
	box.FocusLost:Connect(function(enterPressed)
		Tween(line, { Size = UDim2.new(0, 0, 0, 2) }, 0.15)
		SetFlag(opts, box.Text)
		Safe(opts.Callback, box.Text, enterPressed)
	end)

	local obj = { Instance = card }
	function obj:Set(text, silent)
		box.Text = text
		SetFlag(opts, text)
		if not silent then
			Safe(opts.Callback, text, false)
		end
	end
	function obj:Get()
		return box.Text
	end
	SetFlag(opts, box.Text)
	return obj
end

return Elements
end

modules["UI/Elements/Toggle"] = function(...)
-- On/off toggle.
local import = ...

local Card = import("UI/Card")
local Elements = import("UI/Elements/Base")
local Fonts = import("Core/Fonts")
local FONT = Fonts.FONT
local Util = import("Core/Util")
local Create, Apply, Corner, Safe, SetFlag = Util.Create, Util.Apply, Util.Corner, Util.Safe, Util.SetFlag
local Binding = import("Theme/Binding")
local Bind, NewText, Stroke = Binding.Bind, Binding.NewText, Binding.Stroke

function Elements:AddToggle(opts)
	opts = opts or {}
	local window, theme = self.Window, self.Theme
	local state = opts.Default == true
	local card, _, cy = Card(self, opts, 0.55)

	local click = Create("TextButton", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = "",
		Parent = card,
	})
	local status = NewText(window, card, "", {
		Size = UDim2.fromOffset(40, 20),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -64, 0, cy),
		TextXAlignment = Enum.TextXAlignment.Right,
		Font = FONT,
		TextSize = 13,
	}, function(t)
		return state and t.Text or t.SubText
	end)
	local track = Create("Frame", {
		Size = UDim2.fromOffset(40, 20),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -14, 0, cy),
		BorderSizePixel = 0,
		Parent = card,
	})
	Bind(window, track, "BackgroundColor3", "Accent")
	Corner(track, "pill")
	local trackStroke = Stroke(window, track, function(t)
		return state and t.Accent or t.SubText
	end, 0, 1)
	local knob = Create("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		BorderSizePixel = 0,
		Parent = track,
	})
	Bind(window, knob, "BackgroundColor3", function(t)
		return state and t.AccentText or t.SubText
	end)
	Corner(knob, "pill")

	local obj = { Instance = card }

	local function render(instant)
		Apply(track, { BackgroundTransparency = state and 0 or 1 }, instant)
		Apply(trackStroke, { Color = state and theme.Accent or theme.SubText }, instant)
		Apply(knob, {
			Size = state and UDim2.fromOffset(14, 14) or UDim2.fromOffset(12, 12),
			Position = state and UDim2.new(0, 23, 0.5, 0) or UDim2.new(0, 4, 0.5, 0),
			BackgroundColor3 = state and theme.AccentText or theme.SubText,
		}, instant)
		Apply(status, { TextColor3 = state and theme.Text or theme.SubText }, instant)
		status.Text = state and "On" or "Off"
	end

	function obj:Set(value, silent)
		state = value and true or false
		render(false)
		SetFlag(opts, state)
		if not silent then
			Safe(opts.Callback, state)
		end
	end
	function obj:Get()
		return state
	end

	click.MouseButton1Click:Connect(function()
		obj:Set(not state)
	end)

	render(true)
	SetFlag(opts, state)
	return obj
end

return Elements
end

modules["UI/Logo"] = function(...)
-- The Moon logo: a crescent drawn from thin horizontal slices (no images, no emojis).
-- Pass an asset string (Logo = "rbxassetid://...") to use your own image instead.
local import = ...

local Util = import("Core/Util")
local Create = Util.Create
local Binding = import("Theme/Binding")
local Bind = Binding.Bind

-- the moon is a big disk with a second disk carved out of it (unit coordinates, 0..1)
local DISK = { x = 0.46, y = 0.5, r = 0.44 }
local CUT = { x = 0.64, y = 0.4, r = 0.37 }

local cache = {}

-- returns a list of { x, y, width, height } slices that make up the crescent
local function Crescent(n)
	if cache[n] then
		return cache[n]
	end
	local bars = {}
	for i = 0, n - 1 do
		local y = (i + 0.5) / n
		local dy = y - DISK.y
		if math.abs(dy) < DISK.r then
			local half = math.sqrt(DISK.r ^ 2 - dy ^ 2)
			local a0, a1 = DISK.x - half, DISK.x + half
			local cdy = y - CUT.y
			local pieces
			if math.abs(cdy) < CUT.r then
				local chalf = math.sqrt(CUT.r ^ 2 - cdy ^ 2)
				local c0, c1 = CUT.x - chalf, CUT.x + chalf
				pieces = { { a0, math.min(a1, c0) }, { math.max(a0, c1), a1 } }
			else
				pieces = { { a0, a1 } }
			end
			for _, piece in ipairs(pieces) do
				if piece[2] - piece[1] > 0.004 then
					table.insert(bars, { piece[1], i / n, piece[2] - piece[1], 1 / n })
				end
			end
		end
	end
	cache[n] = bars
	return bars
end

local function CreateLogo(window, parent, size, asset, props)
	local holder = Create("Frame", {
		Name = "Logo",
		Size = UDim2.fromOffset(size, size),
		BackgroundTransparency = 1,
		Parent = parent,
	})
	for k, v in pairs(props or {}) do
		holder[k] = v
	end
	if asset then
		Create("ImageLabel", {
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			Image = asset,
			ScaleType = Enum.ScaleType.Fit,
			Parent = holder,
		})
		return holder
	end

	for _, bar in ipairs(Crescent(math.clamp(math.floor(size), 12, 40))) do
		local slice = Create("Frame", {
			Position = UDim2.fromScale(bar[1], bar[2]),
			Size = UDim2.fromScale(bar[3], bar[4] + 0.012),
			BorderSizePixel = 0,
			Parent = holder,
		})
		Bind(window, slice, "BackgroundColor3", "Accent")
	end

	-- one small star in the bite of the moon (only when there is room for it)
	if size >= 20 then
		local star = Create("Frame", {
			Position = UDim2.fromScale(0.58, 0.24),
			Size = UDim2.fromScale(0.11, 0.11),
			BorderSizePixel = 0,
			Parent = holder,
		}, { Create("UICorner", { CornerRadius = UDim.new(1, 0) }) })
		Bind(window, star, "BackgroundColor3", "Accent")
	end
	return holder
end

return CreateLogo
end

modules["Window/Create"] = function(...)
-- Moon:CreateWindow builds the window; Moon:Unload removes every window.
local import = ...

local Moon = import("Core/Moon")
local CreateLogo = import("UI/Logo")
local Window = import("Window/Window")
local BuildWatermark = import("Window/Watermark")
local BuildPlayerCard = import("Window/PlayerCard")
local BuildOpenButton = import("Window/OpenButton")
local Services = import("Core/Services")
local Players, UserInputService, Lighting, RunService, GuiService = Services.Players, Services.UserInputService, Services.Lighting, Services.RunService, Services.GuiService
local Fonts = import("Core/Fonts")
local FONT, FONT_BOLD = Fonts.FONT, Fonts.FONT_BOLD
local Colors = import("Theme/Colors")
local WHITE = Colors.WHITE
local Util = import("Core/Util")
local Create, Tween, Corner, Pad, List, IsPress, IsMove, GetGuiParent = Util.Create, Util.Tween, Util.Corner, Util.Pad, Util.List, Util.IsPress, Util.IsMove, Util.GetGuiParent
local Registry = import("Theme/Registry")
local ResolveTheme, ALIAS = Registry.ResolveTheme, Registry.ALIAS
local Binding = import("Theme/Binding")
local Bind, Themed, NewText, Stroke = Binding.Bind, Binding.Themed, Binding.NewText, Binding.Stroke

function Moon:CreateWindow(opts)
	opts = opts or {}
	local title = opts.Title or "Moon"

	local self = setmetatable({
		Title = title,
		Tabs = {},
		Theme = {},
		ThemeName = "Moon",
		Visible = true,
		_logo = opts.Logo,
		_conns = {},
		_bindings = {},
		_accentPickers = {},
		_blurSize = 0,
	}, Window)

	-- live theme: every element reads from this one table
	local initial = ResolveTheme(opts.Theme or "Moon")
	for key in pairs(Moon.Themes.Moon) do
		self.Theme[key] = initial[key]
	end
	if type(opts.Theme) == "string" then
		self.ThemeName = ALIAS[opts.Theme] or opts.Theme
	elseif opts.Theme then
		self.ThemeName = "Custom"
	end
	local theme = self.Theme

	if opts.Blur == nil or opts.Blur == true then
		self._blurSize = 12
	elseif type(opts.Blur) == "number" then
		self._blurSize = math.clamp(opts.Blur, 0, 56)
	end

	local parent = opts.Parent or GetGuiParent()
	local guiName = "Moon_" .. title
	for _, leftover in ipairs({ guiName, guiName .. "_Overlay" }) do
		local old = parent:FindFirstChild(leftover)
		if old then
			old:Destroy()
		end
	end
	local oldBlur = Lighting:FindFirstChild("MoonBlur_" .. title)
	if oldBlur then
		oldBlur:Destroy()
	end

	local gui = Create("ScreenGui", {
		Name = guiName,
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 100,
		Parent = parent,
	})
	self.Gui = gui

	-- second layer for the watermark, toasts and open button. It keeps Roblox's default
	-- inset so it sits below the top bar and inside device safe areas (notches).
	local overlay = Create("ScreenGui", {
		Name = guiName .. "_Overlay",
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 101,
		Parent = parent,
	})
	pcall(function()
		overlay.ScreenInsets = Enum.ScreenInsets.TopbarSafeInsets
	end)
	self.Overlay = overlay

	-- fit to small screens unless a size was given
	local size = opts.Size
	if not size then
		local camera = workspace.CurrentCamera
		local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
		size = UDim2.fromOffset(math.min(680, viewport.X - 24), math.min(440, viewport.Y - 24))
	end
	local navWidth = opts.NavWidth or (size.X.Offset > 0 and size.X.Offset < 560 and 124 or 176)

	-- translucent glass window (a CanvasGroup so the whole thing can fade and clip to rounded corners)
	local main = Create("CanvasGroup", {
		Name = "Main",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = size,
		BorderSizePixel = 0,
		Parent = gui,
	})
	Themed(self, main, { BackgroundColor3 = "Background", BackgroundTransparency = "BackgroundTransparency" })
	local mainCorner = Corner(main, 8)
	Stroke(self, main, "Border", "BorderTransparency")
	self.Main = main
	local scale = Create("UIScale", { Parent = main })
	self._scale = scale

	-- soft colored sheen across the glass (fades from top-left to transparent)
	local sheen = Create("Frame", {
		Size = UDim2.fromScale(1, 1),
		BorderSizePixel = 0,
		Parent = main,
	})
	Bind(self, sheen, "BackgroundColor3", "Tint")
	Create("UIGradient", {
		Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.72),
			NumberSequenceKeypoint.new(1, 1),
		}),
		Rotation = 35,
		Parent = sheen,
	})

	-- title bar
	local titlebar = Create("Frame", {
		Size = UDim2.new(1, 0, 0, 36),
		BackgroundTransparency = 1,
		Parent = main,
	})
	CreateLogo(self, titlebar, 16, opts.Logo, {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 12, 0.5, 0),
	})
	NewText(self, titlebar, title, {
		Size = UDim2.new(1, -200, 1, 0),
		Position = UDim2.fromOffset(36, 0),
		Font = FONT,
		TextSize = 12,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	local dragArea = Create("Frame", {
		Size = UDim2.new(1, -134, 1, 0),
		BackgroundTransparency = 1,
		Parent = titlebar,
	})

	local function CaptionButton(index, kind)
		local btn = Create("TextButton", {
			Size = UDim2.fromOffset(40, 28),
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -6 - (index - 1) * 42, 0.5, 0),
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			BorderSizePixel = 0,
			Parent = titlebar,
		})
		Bind(self, btn, "BackgroundColor3", "Text")
		Corner(btn, 6)
		local glyph = Create("Frame", {
			Size = UDim2.fromOffset(10, 10),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			BackgroundTransparency = 1,
			Parent = btn,
		})

		local parts = {}
		if kind == "min" then
			table.insert(parts, Create("Frame", {
				Size = UDim2.new(1, 0, 0, 1),
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				BorderSizePixel = 0,
				Parent = glyph,
			}))
		elseif kind == "max" then
			local outline = Stroke(self, glyph, "Text", 0, 1)
			table.insert(parts, outline)
		else
			for _, rotation in ipairs({ 45, -45 }) do
				table.insert(parts, Create("Frame", {
					Size = UDim2.fromOffset(14, 1),
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromScale(0.5, 0.5),
					Rotation = rotation,
					BorderSizePixel = 0,
					Parent = glyph,
				}))
			end
		end
		local function paint(color)
			for _, part in ipairs(parts) do
				if part:IsA("UIStroke") then
					part.Color = color
				else
					part.BackgroundColor3 = color
				end
			end
		end
		for _, part in ipairs(parts) do
			if not part:IsA("UIStroke") then
				Bind(self, part, "BackgroundColor3", "Text")
			end
		end

		btn.MouseEnter:Connect(function()
			if kind == "close" then
				btn.BackgroundColor3 = theme.Danger
				Tween(btn, { BackgroundTransparency = 0 }, 0.1)
				paint(WHITE)
			else
				Tween(btn, { BackgroundTransparency = 0.9 }, 0.1)
			end
		end)
		btn.MouseLeave:Connect(function()
			Tween(btn, { BackgroundTransparency = 1 }, 0.1)
			paint(theme.Text)
		end)
		return btn
	end

	local closeBtn = CaptionButton(1, "close")
	local maxBtn = CaptionButton(2, "max")
	local minBtn = CaptionButton(3, "min")

	-- body: navigation pane + content
	local body = Create("Frame", {
		Position = UDim2.fromOffset(0, 36),
		Size = UDim2.new(1, 0, 1, -36),
		BackgroundTransparency = 1,
		Parent = main,
	})
	local nav = Create("Frame", {
		Size = UDim2.new(0, navWidth, 1, 0),
		BackgroundTransparency = 1,
		Parent = body,
	})
	local navHeader = Create("Frame", {
		Size = UDim2.new(1, 0, 0, 60),
		BackgroundTransparency = 1,
		Parent = nav,
	})
	CreateLogo(self, navHeader, 32, opts.Logo, {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 16, 0.5, 0),
	})
	NewText(self, navHeader, title, {
		Size = UDim2.new(1, -64, 0, 18),
		Position = UDim2.fromOffset(58, 12),
		Font = FONT_BOLD,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	NewText(self, navHeader, opts.Subtitle or ("v" .. Moon.Version), {
		Size = UDim2.new(1, -64, 0, 16),
		Position = UDim2.fromOffset(58, 31),
		Font = FONT,
		TextSize = 12,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, "SubText")

	local localPlayer = Players.LocalPlayer
	local hasCard = opts.PlayerCard ~= false and localPlayer ~= nil

	local tabBar = Create("ScrollingFrame", {
		Position = UDim2.fromOffset(0, 64),
		Size = UDim2.new(1, 0, 1, -(64 + (hasCard and 68 or 0))),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ScrollBarThickness = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		Parent = nav,
	})
	List(tabBar, 2)
	Pad(tabBar, 8, 4, 8, 8)
	self._tabBar = tabBar

	-- player card (bottom-left): avatar, name and time spent in this game session
	if hasCard then
		BuildPlayerCard(self, nav, gui, navWidth, localPlayer)
	end

	self._pages = Create("Frame", {
		Position = UDim2.fromOffset(navWidth, 0),
		Size = UDim2.new(1, -navWidth, 1, 0),
		BackgroundTransparency = 1,
		Parent = body,
	})

	local isTouch = UserInputService.TouchEnabled

	-- toast notifications: bottom-right on PC, top-right (under the watermark) on touch devices
	-- so they never cover the jump button
	local notifyHolder = Create("Frame", {
		AnchorPoint = isTouch and Vector2.new(1, 0) or Vector2.new(1, 1),
		Position = isTouch and UDim2.new(1, -12, 0, 58) or UDim2.new(1, -16, 1, -16),
		Size = isTouch and UDim2.new(0, 300, 1, -70) or UDim2.new(0, 320, 1, -32),
		BackgroundTransparency = 1,
		Parent = overlay,
	})
	Create("UIListLayout", {
		Padding = UDim.new(0, 8),
		SortOrder = Enum.SortOrder.LayoutOrder,
		VerticalAlignment = isTouch and Enum.VerticalAlignment.Top or Enum.VerticalAlignment.Bottom,
		Parent = notifyHolder,
	})
	self._notifyHolder = notifyHolder

	-- watermark (FPS + ping), top-right of the safe area
	local watermarkOpts = type(opts.Watermark) == "table" and opts.Watermark or { Visible = opts.Watermark ~= false }
	self.Watermark = BuildWatermark(self, overlay, watermarkOpts)

	-- if this client did not apply the top inset to the overlay, offset by the top bar manually
	task.spawn(function()
		RunService.RenderStepped:Wait()
		local camera = workspace.CurrentCamera
		if not overlay.Parent or not camera or camera.ViewportSize.Y - overlay.AbsoluteSize.Y >= 1 then
			return
		end
		local ok, inset = pcall(function()
			return GuiService:GetGuiInset()
		end)
		local top = ok and inset.Y or 0
		self.Watermark.Instance.Position = UDim2.new(1, -12, 0, 12 + top)
		if isTouch then
			notifyHolder.Position = UDim2.new(1, -12, 0, 58 + top)
		end
	end)

	-- open button (draggable, shown while the window is hidden)
	BuildOpenButton(self, overlay, opts)

	-- maximize / restore
	local maximized = false
	local restoreSize, restorePos = size, main.Position
	maxBtn.MouseButton1Click:Connect(function()
		maximized = not maximized
		if maximized then
			restoreSize, restorePos = main.Size, main.Position
			mainCorner.CornerRadius = UDim.new(0, 0)
			Tween(main, { Size = UDim2.fromScale(1, 1), Position = UDim2.fromScale(0.5, 0.5) }, 0.22)
		else
			mainCorner.CornerRadius = UDim.new(0, 8)
			Tween(main, { Size = restoreSize, Position = restorePos }, 0.22)
		end
	end)
	minBtn.MouseButton1Click:Connect(function()
		self:SetVisible(false)
	end)
	closeBtn.MouseButton1Click:Connect(function()
		self:Destroy()
	end)

	-- dragging by the title bar
	local dragging, dragStart, startPos
	dragArea.InputBegan:Connect(function(input)
		if IsPress(input) and not maximized then
			dragging = true
			dragStart = input.Position
			startPos = main.Position
		end
	end)
	self:_connect(UserInputService.InputChanged, function(input)
		if dragging and IsMove(input) then
			local delta = input.Position - dragStart
			main.Position = UDim2.new(
				startPos.X.Scale, startPos.X.Offset + delta.X,
				startPos.Y.Scale, startPos.Y.Offset + delta.Y
			)
		end
	end)
	self:_connect(UserInputService.InputEnded, function(input)
		if IsPress(input) then
			dragging = false
		end
	end)

	-- toggle key
	local toggleKey = opts.ToggleKey or Enum.KeyCode.RightShift
	self:_connect(UserInputService.InputBegan, function(input, gameProcessed)
		if not gameProcessed and input.KeyCode == toggleKey then
			self:Toggle()
		end
	end)

	-- intro animation
	self:_syncBlur()
	main.GroupTransparency = 1
	scale.Scale = 0.95
	Tween(main, { GroupTransparency = 0 }, 0.28)
	Tween(scale, { Scale = 1 }, 0.32, Enum.EasingStyle.Back)

	table.insert(Moon.Windows, self)
	return self
end


function Moon:Unload()
	for _, window in ipairs({ table.unpack(Moon.Windows) }) do
		window:Destroy()
	end
	table.clear(Moon.Flags)
end

return Moon
end

modules["Window/Notify"] = function(...)
-- Toast notifications.
local import = ...

local CreateLogo = import("UI/Logo")
local Window = import("Window/Window")
local Fonts = import("Core/Fonts")
local FONT, FONT_MED, FONT_BOLD = Fonts.FONT, Fonts.FONT_MED, Fonts.FONT_BOLD
local Util = import("Core/Util")
local Create, Tween, Corner = Util.Create, Util.Tween, Util.Corner

function Window:Notify(info)
	info = info or {}
	local theme = self.Theme
	local wrap = Create("Frame", {
		Size = UDim2.new(1, 0, 0, 88),
		BackgroundTransparency = 1,
		Parent = self._notifyHolder,
	})
	local card = Create("TextButton", {
		Size = UDim2.fromScale(1, 1),
		Position = UDim2.new(1, 40, 0, 0),
		BackgroundColor3 = theme.Background,
		BackgroundTransparency = 0.06,
		AutoButtonColor = false,
		Text = "",
		BorderSizePixel = 0,
		Parent = wrap,
	})
	Corner(card, 8)
	local cardStroke = Create("UIStroke", {
		Color = theme.Accent,
		Thickness = 1,
		Transparency = 0.5,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = card,
	})
	CreateLogo(self, card, 12, self._logo, { Position = UDim2.fromOffset(12, 10) })
	local function text(str, props, color)
		local label = Create("TextLabel", {
			BackgroundTransparency = 1,
			Text = str,
			TextColor3 = color,
			Font = FONT_MED,
			TextSize = 14,
			TextXAlignment = Enum.TextXAlignment.Left,
			Parent = card,
		})
		for k, v in pairs(props) do
			label[k] = v
		end
		return label
	end
	text(self.Title, {
		Size = UDim2.new(1, -40, 0, 14),
		Position = UDim2.fromOffset(32, 10),
		Font = FONT,
		TextSize = 11,
	}, theme.SubText)
	text(info.Title or "Notification", {
		Size = UDim2.new(1, -24, 0, 20),
		Position = UDim2.fromOffset(12, 28),
		Font = FONT_BOLD,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, theme.Text)
	text(info.Content or "", {
		Size = UDim2.new(1, -24, 0, 32),
		Position = UDim2.fromOffset(12, 48),
		Font = FONT,
		TextSize = 13,
		TextWrapped = true,
		TextYAlignment = Enum.TextYAlignment.Top,
	}, theme.SubText)
	Tween(card, { Position = UDim2.new(0, 0, 0, 0) }, 0.32, Enum.EasingStyle.Back)
	Tween(cardStroke, { Transparency = 0.8 }, 1.2)

	local gone = false
	local function dismiss()
		if gone then
			return
		end
		gone = true
		Tween(card, { Position = UDim2.new(1, 40, 0, 0) }, 0.25)
		task.wait(0.3)
		wrap:Destroy()
	end
	card.MouseButton1Click:Connect(function()
		task.spawn(dismiss)
	end)
	task.delay(info.Duration or 4, dismiss)
end

return Window
end

modules["Window/OpenButton"] = function(...)
-- Draggable open button shown while the window is hidden. Hold and drag to move, tap to open.
local import = ...

local CreateLogo = import("UI/Logo")
local Services = import("Core/Services")
local UserInputService = Services.UserInputService
local Util = import("Core/Util")
local Create, Tween, Corner, IsPress, IsMove = Util.Create, Util.Tween, Util.Corner, Util.IsPress, Util.IsMove
local Binding = import("Theme/Binding")
local Bind, Stroke = Binding.Bind, Binding.Stroke

local function BuildOpenButton(self, overlay, opts)
	local tray = Create("Frame", {
		Name = "OpenButton",
		Size = UDim2.fromOffset(52, 44),
		Position = UDim2.new(0.5, -26, 1, -64),
		BackgroundTransparency = 0.1,
		BorderSizePixel = 0,
		Active = true,
		Visible = false,
		Parent = overlay,
	})
	Bind(self, tray, "BackgroundColor3", "Background")
	Corner(tray, 10)
	Stroke(self, tray, "Border", "BorderTransparency")
	CreateLogo(self, tray, 22, opts.Logo, {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, -3),
	})
	local indicator = Create("Frame", {
		Size = UDim2.fromOffset(14, 3),
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -4),
		BorderSizePixel = 0,
		Parent = tray,
	})
	Bind(self, indicator, "BackgroundColor3", "Accent")
	Corner(indicator, "pill")
	self._tray = tray
	self._trayScale = Create("UIScale", { Parent = tray })

	local trayDragging, trayMoved, trayStart, trayOrigin, trayInput
	tray.InputBegan:Connect(function(input)
		if IsPress(input) then
			trayDragging, trayMoved = true, false
			trayInput = input
			trayStart = input.Position
			trayOrigin = tray.AbsolutePosition - overlay.AbsolutePosition
			Tween(tray, { BackgroundTransparency = 0.02 }, 0.08)
			Tween(self._trayScale, { Scale = 0.94 }, 0.08)
		end
	end)
	self:_connect(UserInputService.InputChanged, function(input)
		if not trayDragging or not IsMove(input) then
			return
		end
		if input.UserInputType == Enum.UserInputType.Touch and input ~= trayInput then
			return
		end
		local delta = input.Position - trayStart
		if not trayMoved and delta.Magnitude > 6 then
			trayMoved = true
		end
		if trayMoved then
			local view, traySize = overlay.AbsoluteSize, tray.AbsoluteSize
			tray.Position = UDim2.fromOffset(
				math.clamp(trayOrigin.X + delta.X, 6, math.max(6, view.X - traySize.X - 6)),
				math.clamp(trayOrigin.Y + delta.Y, 6, math.max(6, view.Y - traySize.Y - 6))
			)
		end
	end)
	self:_connect(UserInputService.InputEnded, function(input)
		if not trayDragging or not IsPress(input) then
			return
		end
		if input.UserInputType == Enum.UserInputType.Touch and input ~= trayInput then
			return
		end
		trayDragging = false
		Tween(tray, { BackgroundTransparency = 0.1 }, 0.1)
		Tween(self._trayScale, { Scale = 1 }, 0.15)
		if not trayMoved then
			self:SetVisible(true)
		end
	end)
end

return BuildOpenButton
end

modules["Window/PlayerCard"] = function(...)
-- Player card (bottom-left of the navigation pane): avatar, name and session playtime.
local import = ...

local Services = import("Core/Services")
local Players = Services.Players
local Fonts = import("Core/Fonts")
local FONT = Fonts.FONT
local Util = import("Core/Util")
local Create, Corner = Util.Create, Util.Corner
local Binding = import("Theme/Binding")
local Bind, Themed, NewText, Stroke = Binding.Bind, Binding.Themed, Binding.NewText, Binding.Stroke

local function SessionSeconds()
	local ok, seconds = pcall(time)
	if ok and type(seconds) == "number" then
		return seconds
	end
	return os.clock()
end

local function FormatTime(seconds)
	seconds = math.floor(seconds)
	return string.format(
		"%d:%02d:%02d",
		math.floor(seconds / 3600),
		math.floor((seconds % 3600) / 60),
		seconds % 60
	)
end

local function BuildPlayerCard(self, nav, gui, navWidth, localPlayer)
	local card = Create("Frame", {
		Name = "PlayerCard",
		Size = UDim2.new(1, -16, 0, 52),
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 8, 1, -8),
		BorderSizePixel = 0,
		Parent = nav,
	})
	Themed(self, card, { BackgroundColor3 = "Card", BackgroundTransparency = "CardTransparency" })
	Corner(card, 8)
	Stroke(self, card, "Stroke", "StrokeTransparency")

	local avatar = Create("ImageLabel", {
		Size = UDim2.fromOffset(34, 34),
		Position = UDim2.fromOffset(9, 9),
		BorderSizePixel = 0,
		ScaleType = Enum.ScaleType.Crop,
		Image = "",
		Parent = card,
	})
	Themed(self, avatar, { BackgroundColor3 = "Control", BackgroundTransparency = "ControlTransparency" })
	Corner(avatar, "pill")
	Stroke(self, avatar, "Accent", 0.3, 1.5)

	local dot = Create("Frame", {
		Size = UDim2.fromOffset(10, 10),
		Position = UDim2.fromOffset(34, 34),
		BorderSizePixel = 0,
		ZIndex = 2,
		Parent = card,
	})
	Bind(self, dot, "BackgroundColor3", "Good")
	Corner(dot, "pill")
	Stroke(self, dot, "Background", 0, 2)

	NewText(self, card, localPlayer.DisplayName, {
		Size = UDim2.new(1, -56, 0, 16),
		Position = UDim2.fromOffset(51, 10),
		TextSize = 13,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	local timeLabel = NewText(self, card, "", {
		Size = UDim2.new(1, -56, 0, 14),
		Position = UDim2.fromOffset(51, 27),
		Font = FONT,
		TextSize = 12,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, "SubText")

	task.spawn(function()
		local ok, content = pcall(function()
			return Players:GetUserThumbnailAsync(
				localPlayer.UserId,
				Enum.ThumbnailType.HeadShot,
				Enum.ThumbnailSize.Size100x100
			)
		end)
		if ok and avatar.Parent then
			avatar.Image = content
		end
	end)

	local prefix = navWidth >= 150 and "Playtime " or ""
	task.spawn(function()
		while gui.Parent do
			timeLabel.Text = prefix .. FormatTime(SessionSeconds())
			task.wait(1)
		end
	end)
end

return BuildPlayerCard
end

modules["Window/Tab"] = function(...)
-- Tabs (navigation pane entries + their pages).
local import = ...

local Elements = import("UI/Elements/Base")
local Window = import("Window/Window")
local Fonts = import("Core/Fonts")
local FONT_SERIF = Fonts.FONT_SERIF
local Util = import("Core/Util")
local Create, Tween, Corner, Pad, List = Util.Create, Util.Tween, Util.Corner, Util.Pad, Util.List
local Binding = import("Theme/Binding")
local Bind, NewText = Binding.Bind, Binding.NewText

function Window:AddTab(name)
	local window = self
	local theme = self.Theme

	local tab = setmetatable({
		Theme = theme,
		Window = window,
		_active = false,
	}, { __index = Elements })

	local button = Create("TextButton", {
		Size = UDim2.new(1, 0, 0, 36),
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Text = "",
		BorderSizePixel = 0,
		Parent = self._tabBar,
	})
	Bind(window, button, "BackgroundColor3", "Text")
	Corner(button, 6)
	local pill = Create("Frame", {
		Size = UDim2.fromOffset(3, 0),
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
		BorderSizePixel = 0,
		Parent = button,
	})
	Bind(window, pill, "BackgroundColor3", "Accent")
	Corner(pill, "pill")
	local label = NewText(window, button, name or "Tab", {
		Size = UDim2.new(1, -22, 1, 0),
		Position = UDim2.fromOffset(14, 0),
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, function(t)
		return tab._active and t.Text or t.SubText
	end)

	local holder = Create("CanvasGroup", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = self._pages,
	})
	local page = Create("ScrollingFrame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ScrollBarThickness = 3,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		Parent = holder,
	})
	Bind(window, page, "ScrollBarImageColor3", "Accent")
	List(page, 6)
	Pad(page, 8, 4, 16, 16)
	NewText(window, page, name or "Tab", {
		Size = UDim2.new(1, 0, 0, 44),
		Font = FONT_SERIF,
		TextSize = 24,
		LayoutOrder = -1,
	})

	tab.Container = page
	tab.Page = page
	tab._holder = holder
	tab._button = button
	tab._pill = pill
	tab._label = label
	table.insert(self.Tabs, tab)

	function tab:Select()
		for _, other in ipairs(window.Tabs) do
			local active = other == self
			if active and not other._active then
				other._holder.Visible = true
				other._holder.GroupTransparency = 1
				other._holder.Position = UDim2.fromOffset(0, 14)
				Tween(other._holder, { GroupTransparency = 0, Position = UDim2.fromOffset(0, 0) }, 0.24)
			elseif not active then
				other._holder.Visible = false
			end
			other._active = active
			Tween(other._pill, { Size = UDim2.fromOffset(3, active and 16 or 0) }, 0.2, Enum.EasingStyle.Back)
			Tween(other._button, { BackgroundTransparency = active and 0.91 or 1 }, 0.15)
			Tween(other._label, { TextColor3 = active and theme.Text or theme.SubText }, 0.15)
		end
	end

	button.MouseEnter:Connect(function()
		if not tab._active then
			Tween(button, { BackgroundTransparency = 0.94 }, 0.1)
		end
	end)
	button.MouseLeave:Connect(function()
		if not tab._active then
			Tween(button, { BackgroundTransparency = 1 }, 0.1)
		end
	end)
	button.MouseButton1Click:Connect(function()
		tab:Select()
	end)

	if #self.Tabs == 1 then
		tab:Select()
	end
	return tab
end

return Window
end

modules["Window/Watermark"] = function(...)
-- FPS + ping watermark card.
local import = ...

local CreateLogo = import("UI/Logo")
local Services = import("Core/Services")
local Players, RunService, Stats = Services.Players, Services.RunService, Services.Stats
local Fonts = import("Core/Fonts")
local FONT, FONT_BOLD = Fonts.FONT, Fonts.FONT_BOLD
local Util = import("Core/Util")
local Create, Tween, Corner, Pad = Util.Create, Util.Tween, Util.Corner, Util.Pad
local Binding = import("Theme/Binding")
local Bind, NewText, Stroke = Binding.Bind, Binding.NewText, Binding.Stroke

local function GetPing()
	local ok, ms = pcall(function()
		return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
	end)
	if ok and type(ms) == "number" then
		return math.floor(ms + 0.5)
	end
	local lp = Players.LocalPlayer
	local ok2, seconds = pcall(function()
		return lp:GetNetworkPing()
	end)
	if ok2 and type(seconds) == "number" then
		return math.floor(seconds * 1000 + 0.5)
	end
	return nil
end

local function StatusColor(theme, level)
	if level == 1 then
		return theme.Good
	elseif level == 2 then
		return theme.Warn
	end
	return theme.Bad
end

local function BuildWatermark(window, overlay, opts)
	local visible = opts.Visible ~= false
	local holder = Create("CanvasGroup", {
		Name = "Watermark",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -12, 0, 12),
		Size = UDim2.fromOffset(0, 34),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 0.08,
		BorderSizePixel = 0,
		Visible = visible,
		Parent = overlay,
	})
	Bind(window, holder, "BackgroundColor3", "Background")
	Corner(holder, 8)
	Stroke(window, holder, "Border", "BorderTransparency")
	Pad(holder, 5, 0, 12, 0)
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		SortOrder = Enum.SortOrder.LayoutOrder,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, 8),
		Parent = holder,
	})

	local chip = Create("Frame", {
		Size = UDim2.fromOffset(24, 24),
		BackgroundTransparency = 0.82,
		BorderSizePixel = 0,
		LayoutOrder = 1,
		Parent = holder,
	})
	Bind(window, chip, "BackgroundColor3", "Accent")
	Corner(chip, 6)
	CreateLogo(window, chip, 14, window._logo, {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
	})
	local title = NewText(window, holder, opts.Text or window.Title, {
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 2,
		Font = FONT_BOLD,
		TextSize = 13,
	})

	local function Divider(order)
		local line = Create("Frame", {
			Size = UDim2.fromOffset(1, 16),
			BackgroundTransparency = 0.85,
			BorderSizePixel = 0,
			LayoutOrder = order,
			Parent = holder,
		})
		Bind(window, line, "BackgroundColor3", "Text")
	end

	local function Stat(label, order, valueWidth)
		local group = Create("Frame", {
			Size = UDim2.fromScale(0, 1),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			LayoutOrder = order,
			Parent = holder,
		})
		Create("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 5),
			Parent = group,
		})
		NewText(window, group, label, {
			Size = UDim2.fromScale(0, 1),
			AutomaticSize = Enum.AutomaticSize.X,
			LayoutOrder = 1,
			Font = FONT,
			TextSize = 11,
		}, "SubText")
		return NewText(window, group, "--", {
			Size = UDim2.new(0, valueWidth, 1, 0),
			LayoutOrder = 2,
			Font = FONT_BOLD,
			TextSize = 13,
		})
	end

	Divider(3)
	local fpsValue = Stat("FPS", 4, 26)
	Divider(5)
	local pingValue = Stat("PING", 6, 46)

	local frames, elapsed = 0, 0
	window:_connect(RunService.RenderStepped, function(dt)
		if not visible then
			frames, elapsed = 0, 0
			return
		end
		frames = frames + 1
		elapsed = elapsed + dt
		if elapsed < 0.5 then
			return
		end
		local theme = window.Theme
		local fps = math.floor(frames / elapsed + 0.5)
		frames, elapsed = 0, 0
		fpsValue.Text = tostring(fps)
		fpsValue.TextColor3 = StatusColor(theme, fps >= 55 and 1 or (fps >= 30 and 2 or 3))
		local ping = GetPing()
		if ping then
			pingValue.Text = ping .. " ms"
			pingValue.TextColor3 = StatusColor(theme, ping <= 80 and 1 or (ping <= 160 and 2 or 3))
		else
			pingValue.Text = "--"
		end
	end)

	local obj = { Instance = holder }
	function obj:SetVisible(value)
		value = value and true or false
		if value == visible then
			return
		end
		visible = value
		if visible then
			holder.Visible = true
			holder.GroupTransparency = 1
			Tween(holder, { GroupTransparency = 0 }, 0.2)
		else
			Tween(holder, { GroupTransparency = 1 }, 0.15)
			task.delay(0.16, function()
				if not visible then
					holder.Visible = false
				end
			end)
		end
	end
	function obj:Toggle()
		obj:SetVisible(not visible)
	end
	function obj:IsVisible()
		return visible
	end
	function obj:SetTitle(text)
		title.Text = text
	end
	return obj
end

return BuildWatermark
end

modules["Window/Window"] = function(...)
-- The Window class: visibility, blur, theme switching and cleanup.
local import = ...

local Moon = import("Core/Moon")
local Services = import("Core/Services")
local TweenService, Lighting = Services.TweenService, Services.Lighting
local Colors = import("Theme/Colors")
local Luma, AccentKeys = Colors.Luma, Colors.AccentKeys
local Util = import("Core/Util")
local Create, Tween = Util.Create, Util.Tween
local Registry = import("Theme/Registry")
local ResolveTheme, ALIAS = Registry.ResolveTheme, Registry.ALIAS

local Window = {}
Window.__index = Window

function Window:_connect(signal, fn)
	local connection = signal:Connect(fn)
	table.insert(self._conns, connection)
	return connection
end

-- Roblox cannot blur UI itself, so the glass look uses a BlurEffect on the game world
-- behind the (translucent) window. It fades in/out with the window.
function Window:_syncBlur()
	local target = (self.Visible and self._blurSize) or 0
	if target > 0 and not self._blur then
		self._blur = Create("BlurEffect", {
			Name = "MoonBlur_" .. self.Title,
			Size = 0,
			Parent = Lighting,
		})
	end
	local blur = self._blur
	if not blur then
		return
	end
	if target > 0 then
		blur.Enabled = true
	end
	local tween = Tween(blur, { Size = target }, 0.3)
	tween.Completed:Connect(function()
		if blur.Parent and blur.Size <= 0 then
			blur.Enabled = false
		end
	end)
end

function Window:SetBlur(size)
	if size == true then
		size = 12
	elseif not size then
		size = 0
	end
	self._blurSize = math.clamp(size, 0, 56)
	self:_syncBlur()
end

function Window:SetVisible(visible)
	visible = visible and true or false
	self.Visible = visible
	self._tray.Visible = not visible
	self:_syncBlur()
	if visible then
		self.Main.Visible = true
		self.Main.GroupTransparency = 1
		self._scale.Scale = 0.95
		Tween(self.Main, { GroupTransparency = 0 }, 0.2)
		Tween(self._scale, { Scale = 1 }, 0.25, Enum.EasingStyle.Back)
	else
		self._trayScale.Scale = 0.6
		Tween(self._trayScale, { Scale = 1 }, 0.28, Enum.EasingStyle.Back)
		Tween(self.Main, { GroupTransparency = 1 }, 0.14)
		Tween(self._scale, { Scale = 0.95 }, 0.14)
		task.delay(0.15, function()
			if not self.Visible and self.Main.Parent then
				self.Main.Visible = false
			end
		end)
	end
end

function Window:Toggle()
	self:SetVisible(not self.Visible)
end

-- Smoothly fades every themed color from the current theme to the new one.
-- theme: a registered theme name, a full theme table, or { Background =, Accent = } (built automatically)
function Window:SetTheme(theme, instant)
	local new = ResolveTheme(theme)
	local info = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut)
	for i = #self._bindings, 1, -1 do
		local binding = self._bindings[i]
		if not binding.inst.Parent then
			table.remove(self._bindings, i)
		else
			local target = binding.get(new)
			if instant then
				binding.inst[binding.prop] = target
			else
				TweenService:Create(binding.inst, info, { [binding.prop] = target }):Play()
			end
		end
	end
	for key in pairs(Moon.Themes.Moon) do
		self.Theme[key] = new[key]
	end
	if type(theme) == "string" then
		self.ThemeName = ALIAS[theme] or theme
	else
		self.ThemeName = "Custom"
	end
	for _, picker in ipairs(self._accentPickers) do
		picker:Set(self.Theme.Accent, true)
	end
end

-- Changes only the accent color (used by the accent color picker)
function Window:SetAccent(color)
	local new = {}
	for key in pairs(Moon.Themes.Moon) do
		new[key] = self.Theme[key]
	end
	for key, value in pairs(AccentKeys(color)) do
		new[key] = value
	end
	local light = Luma(self.Theme.Background) > 0.5
	new.Tint = self.Theme.Background:Lerp(color, light and 0.1 or 0.2)
	self:SetTheme(new)
end

function Window:Destroy()
	for _, connection in ipairs(self._conns) do
		connection:Disconnect()
	end
	table.clear(self._conns)
	local index = table.find(Moon.Windows, self)
	if index then
		table.remove(Moon.Windows, index)
	end
	if self._blur then
		self._blur:Destroy()
	end
	self.Gui:Destroy()
	if self.Overlay then
		self.Overlay:Destroy()
	end
end

return Window
end

local cache = {}

local function import(name)
	local cached = cache[name]
	if cached ~= nil then
		return cached
	end
	local loader = modules[name]
	assert(loader, "[Moon] unknown module: " .. tostring(name))
	local result = loader(import)
	if result == nil then
		result = true
	end
	cache[name] = result
	return result
end

return import("Main")
